contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit `amount` into C, then call withdrawAll once; if it does not revert then calling withdrawAll a second time
    // must not transfer any additional Ether to this contract (i.e., second call either reverts or results in no net gain).
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record this contract balance before any interaction
        uint before = address(this).balance;

        // deposit into C
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // first withdrawAll, capture whether it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // balance after first withdraw
        uint afterFirst = address(this).balance;

        // second withdrawAll, capture whether it reverted
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // balance after second withdraw
        uint afterSecond = address(this).balance;

        // If the first withdraw did not revert, then the second withdraw must not increase this contract's balance.
        // (This encodes that a successful withdraw cleared the recorded credit.)
        assert(firstReverted || afterSecond <= afterFirst);
    }

    // allow receiving Ether from C during withdrawAll
    receive() external payable {}
}

